using System.Net;
using System.Net.Http.Json;
using System.Net.Http.Headers;
using System.Text.Json;
using BuildingFlow.Application;
using BuildingFlow.Domain;
using BuildingFlow.Infrastructure;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Infrastructure;
using Microsoft.EntityFrameworkCore.Migrations;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Npgsql;
using Xunit;
namespace BuildingFlow.IntegrationTests;
public sealed class ListingApiTests(SiteApiTests.SiteApiFactory factory):IClassFixture<SiteApiTests.SiteApiFactory>{
 private static string Root(Guid p)=>$"/api/v1/properties/{p}/listings";
 private static ListingEdit Edit(Guid? unit=null)=>new(Guid.NewGuid(),unit,"SALE","Fixture public title","Public description",7500000,"3+1",145,120,"5. Kat","A Blok",["BALCONY"]);
 private async Task<(Property P,string Actor,WebsiteSite Site,HttpClient Client)> Seed(){var p=new Property("Fixture","City","District","Private address",PropertyType.APARTMENT);var actor=Guid.NewGuid().ToString();var site=new WebsiteSite(p.Id,Guid.NewGuid(),"listing-"+actor[..8],"Fixture");await factory.WithDb(async db=>{db.AddRange(p,new PropertyMembership(p.Id,actor),site);await db.SaveChangesAsync();});return(p,actor,site,TestToken.Client(factory,actor,"SITE_ADMIN"));}
 private static async Task<ListingDto> Saved(HttpResponseMessage response){Assert.Equal(HttpStatusCode.OK,response.StatusCode);return(await response.Content.ReadFromJsonAsync<ListingDto>())!;}
 [PostgresFact]public async Task ScopeRolesReplayVersionsAndUnitAreEnforced(){var x=await Seed();using var c=x.Client;using var anon=factory.CreateClient();using var outsider=TestToken.Client(factory,Guid.NewGuid().ToString(),"SITE_ADMIN");using var accountant=TestToken.Client(factory,x.Actor,"ACCOUNTANT");Assert.Equal(HttpStatusCode.Unauthorized,(await anon.GetAsync(Root(x.P.Id))).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await accountant.GetAsync(Root(x.P.Id))).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await outsider.GetAsync(Root(x.P.Id))).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await c.PostAsJsonAsync(Root(x.P.Id),Edit(Guid.NewGuid()))).StatusCode);var r=Edit();var l=await Saved(await c.PostAsJsonAsync(Root(x.P.Id),r));Assert.True((await Saved(await c.PostAsJsonAsync(Root(x.P.Id),r))).Replayed);Assert.Equal(HttpStatusCode.Conflict,(await c.PostAsJsonAsync(Root(x.P.Id),r with{Title="Different"})).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await c.PutAsJsonAsync(Root(x.P.Id)+"/"+l.Id,r with{Version=l.Version+1})).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await c.PutAsJsonAsync(Root(x.P.Id)+$"/{l.Id}/photos",new ListingPhotos(l.Version,[Guid.NewGuid()]))).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await c.PostAsJsonAsync(Root(x.P.Id)+$"/{l.Id}/submit",new ListingAction(l.Version))).StatusCode);Assert.Equal(HttpStatusCode.NoContent,(await c.DeleteAsync(Root(x.P.Id)+$"/{l.Id}?version={l.Version}")).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await c.PostAsJsonAsync(Root(x.P.Id),r)).StatusCode);}
 [PostgresFact]public async Task UnitAssociationNeverChangesOccupancyAndCompositeScopeIsEnforced(){var x=await Seed();using var c=x.Client;Guid unitId=Guid.Empty;long version=0;await factory.WithDb(async db=>{var p=await db.Properties.SingleAsync(p=>p.Id==x.P.Id);var unit=p.AddUnit("1",1,100);db.Add(unit);await db.SaveChangesAsync();unitId=unit.Id;version=unit.Version;});var l=await Saved(await c.PostAsJsonAsync(Root(x.P.Id),Edit(unitId)));Assert.Equal(unitId,l.UnitId);Assert.Equal(HttpStatusCode.OK,(await c.GetAsync(Root(x.P.Id)+"/"+l.Id)).StatusCode);await factory.WithDb(async db=>{var unit=await db.Units.SingleAsync(u=>u.Id==unitId);Assert.Equal(version,unit.Version);Assert.Equal(0,await db.Set<UnitOccupancy>().CountAsync(u=>u.UnitId==unitId));});var other=await Seed();using var otherClient=other.Client;Assert.Equal(HttpStatusCode.BadRequest,(await otherClient.PostAsJsonAsync(Root(other.P.Id),Edit(unitId))).StatusCode);var options=(await c.GetFromJsonAsync<ListingUnitOption[]>(Root(x.P.Id)+"/unit-options"))!;Assert.Equal(unitId,Assert.Single(options).Id);await factory.WithDb(async db=>{await Assert.ThrowsAsync<PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE property_listings SET property_id={other.P.Id} WHERE id={l.Id}"));});}
 [StorageFact]public async Task PrivateEvidenceAndReviewNeverBypassEids(){var x=await Seed();using var c=x.Client;var l=await Saved(await c.PostAsJsonAsync(Root(x.P.Id),Edit()));using var form=new MultipartFormDataContent();var bytes=System.Text.Encoding.ASCII.GetBytes("%PDF-1.4\nfixture evidence\n%%EOF");var file=new ByteArrayContent(bytes);file.Headers.ContentType=new MediaTypeHeaderValue("application/pdf");form.Add(file,"file","consent.pdf");form.Add(new StringContent(l.Version.ToString()),"version");form.Add(new StringContent("WRITTEN_STATEMENT"),"kind");l=await Saved(await c.PostAsync(Root(x.P.Id)+$"/{l.Id}/owner-consent",form));Assert.Equal(bytes,await c.GetByteArrayAsync(Root(x.P.Id)+$"/{l.Id}/owner-consent"));using var anon=factory.CreateClient();Assert.Equal(HttpStatusCode.Unauthorized,(await anon.GetAsync(Root(x.P.Id)+$"/{l.Id}/owner-consent")).StatusCode);
 var media=new WebsiteMedia(x.P.Id,x.Site.Id,Guid.NewGuid(),new string('a',64),"image/png",1,1,1,new string('b',64),"Alt","OWN_WORK",null,false,false);await factory.WithDb(async db=>{db.Add(media);await db.SaveChangesAsync();});l=await Saved(await c.PutAsJsonAsync(Root(x.P.Id)+$"/{l.Id}/photos",new ListingPhotos(l.Version,[media.Id])));l=await Saved(await c.PostAsJsonAsync(Root(x.P.Id)+$"/{l.Id}/submit",new ListingAction(l.Version)));using var manager=TestToken.Client(factory,x.Actor,"MANAGER");Assert.Equal(HttpStatusCode.Forbidden,(await manager.PostAsJsonAsync(Root(x.P.Id)+$"/{l.Id}/approve",new ListingAction(l.Version,"Reviewed",true))).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await c.PostAsJsonAsync(Root(x.P.Id)+$"/{l.Id}/approve",new ListingAction(l.Version,"Reviewed",false))).StatusCode);l=await Saved(await c.PostAsJsonAsync(Root(x.P.Id)+$"/{l.Id}/approve",new ListingAction(l.Version,"Reviewed authority and privacy",true)));var publish=await c.PostAsJsonAsync(Root(x.P.Id)+$"/{l.Id}/publish",new ListingAction(l.Version,PublishUntil:DateTimeOffset.UtcNow.AddDays(30)));Assert.Equal(HttpStatusCode.Conflict,publish.StatusCode);Assert.Contains("BF_LISTING_VERIFICATION_REQUIRED",await publish.Content.ReadAsStringAsync());Assert.Equal(HttpStatusCode.Conflict,(await c.DeleteAsync(Root(x.P.Id)+$"/{l.Id}?version={l.Version}")).StatusCode);l=await Saved(await c.PutAsJsonAsync(Root(x.P.Id)+"/"+l.Id,Edit() with{Title="Changed",Version=l.Version}));Assert.Equal("PENDING_APPROVAL",l.Status);Assert.Null(l.ComplianceNote);await factory.WithDb(async db=>{await Assert.ThrowsAsync<PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE listing_events SET action={"ALTERED"} WHERE listing_id={l.Id}"));await Assert.ThrowsAsync<PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"DELETE FROM listing_events WHERE listing_id={l.Id}"));});}
 [PostgresFact]public async Task PublishedReadIsWhiteListedAndExpiresWithoutWorker(){var x=await Seed();using var c=x.Client;var l=new PropertyListing(x.P.Id,x.Site.Id,Guid.NewGuid(),new string('a',64));var now=DateTimeOffset.UtcNow;l.Edit(null,"RENT","Public","Description",28000,"2+1",95,80,null,null,"[]");l.Consent("WRITTEN_STATEMENT","private-secret",new string('b',64),"application/pdf",1,null);l.Transition("SUBMIT",null,now);l.Transition("APPROVE","Private compliance",now);l.Transition("PUBLISH",null,now,now.AddDays(1),"fixture-verifier");await factory.WithDb(async db=>{var site=await db.Set<WebsiteSite>().SingleAsync(s=>s.Id==x.Site.Id);site.MarkPublished();db.AddRange(l,new WebsitePublication(x.P.Id,x.Site.Id,Guid.NewGuid(),1,"{}",new string('c',64),now,null,null));await db.SaveChangesAsync();});using var anon=factory.CreateClient();var path=$"/api/public/v1/sites/{x.Site.SiteKey}/listings/{l.Id}";var response=await anon.GetAsync(path);Assert.Equal(HttpStatusCode.OK,response.StatusCode);var raw=await response.Content.ReadAsStringAsync();foreach(var forbidden in new[]{"propertyId","unitId","personId","createdBy","version","Private address","private-secret","Private compliance","consent"})Assert.DoesNotContain(forbidden,raw);Assert.Contains("MONTHLY",raw);var list=await anon.GetAsync($"/api/public/v1/sites/{x.Site.SiteKey}/listings");Assert.Equal(HttpStatusCode.OK,list.StatusCode);Assert.Contains(l.Id.ToString(),await list.Content.ReadAsStringAsync());Assert.Equal(HttpStatusCode.NotFound,(await anon.GetAsync(path.Replace(x.Site.SiteKey,"missing-site"))).StatusCode);await factory.WithDb(async db=>{await db.Database.ExecuteSqlInterpolatedAsync($"UPDATE property_listings SET publish_until={now.AddDays(-1)} WHERE id={l.Id}");});Assert.Equal(HttpStatusCode.NotFound,(await anon.GetAsync(path)).StatusCode);await factory.WithDb(async db=>{await new WebsiteInquiryStore(db,TimeProvider.System,null!).Retain(default);Assert.Equal("EXPIRED",(await db.Set<PropertyListing>().SingleAsync(x=>x.Id==l.Id)).Status);Assert.True(await db.Set<ListingEvent>().AnyAsync(x=>x.ListingId==l.Id&&x.Action=="EXPIRE"));});}
 [PostgresFact]public async Task InquiryHttpRejectsOversizedAndMalformedBodies(){using var c=factory.CreateClient();var path="/api/public/v1/sites/fixture-site/inquiries";Assert.Equal(HttpStatusCode.BadRequest,(await c.PostAsync(path,new StringContent(new string('x',17000),System.Text.Encoding.UTF8,"application/json"))).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await c.PostAsync(path,new StringContent("null",System.Text.Encoding.UTF8,"application/json"))).StatusCode);}
 [PostgresFact]public async Task InquiryVersionSpamBudgetScopeAndRetention(){var x=await Seed();using var c=x.Client;var now=DateTimeOffset.Parse("2026-10-18T12:00:00Z");var clock=new Clock(now);var protection=new WebsiteInquiryProtection(new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"Website:InquiryHmacKey",Convert.ToBase64String(new byte[32])}}).Build(),clock);var snapshot=JsonSerializer.Serialize(new{pages=new[]{new{kind="PRIVACY",slug="privacy"}}});await factory.WithDb(async db=>{var site=await db.Set<WebsiteSite>().SingleAsync(s=>s.Id==x.Site.Id);site.MarkPublished();db.Add(new WebsitePublication(x.P.Id,x.Site.Id,Guid.NewGuid(),1,snapshot,new string('a',64),now,null,null));await db.SaveChangesAsync();});
 await factory.WithDb(async db=>{var store=new PublicWebsiteInquiryStore(db,clock,protection);var challenge=(await store.Challenge(x.Site.SiteKey,"127.0.0.1",default))!;var request=new InquiryRequest(null,"Fixture visitor","123",null,"Question",challenge.PrivacyNoticeVersion,challenge.Token,null);await Assert.ThrowsAsync<RequestValidationException>(()=>store.Submit(x.Site.SiteKey,"127.0.0.1",request,default));clock.Now=now.AddSeconds(4);for(int i=0;i<5;i++)Assert.True(await store.Submit(x.Site.SiteKey,"127.0.0.1",request,default));await Assert.ThrowsAsync<InquiryRateLimitException>(()=>store.Submit(x.Site.SiteKey,"127.0.0.1",request,default));Assert.True(await store.Submit(x.Site.SiteKey,"127.0.0.1",request with{Website="bot"},default));Assert.Equal(5,await db.Set<WebsiteInquiry>().CountAsync(v=>v.SiteId==x.Site.Id));clock.Now=now.AddDays(181);await new WebsiteInquiryStore(db,clock,null!).Retain(default);var row=await db.Set<WebsiteInquiry>().FirstAsync(v=>v.SiteId==x.Site.Id);Assert.False(row.IsEnabled);Assert.Null(row.Phone);Assert.Equal("",row.IpHash);});using var accountant=TestToken.Client(factory,x.Actor,"ACCOUNTANT");Assert.Equal(HttpStatusCode.Forbidden,(await accountant.GetAsync($"/api/v1/properties/{x.P.Id}/website/inquiries")).StatusCode);}
 [PostgresFact]public async Task AnonymousPublicReadsReachHandlersAndHideUnknownSites(){using var anon=factory.CreateClient();var key="missing-"+Guid.NewGuid().ToString("N")[..8];foreach(var path in new[]{$"/api/public/v1/sites/{key}/listings",$"/api/public/v1/sites/{key}/inquiries/challenge",$"/api/public/v1/sites/{key}/primary-domain"}){var response=await anon.GetAsync(path);Assert.Equal(HttpStatusCode.NotFound,response.StatusCode);Assert.Equal("no-store",response.Headers.CacheControl!.ToString());}}
 private sealed class Clock(DateTimeOffset now):TimeProvider{public DateTimeOffset Now=now;public override DateTimeOffset GetUtcNow()=>Now;}
}
